        [Serializable]sealed class Result{public string name;public bool passed;}
        [Serializable]sealed class Report{public bool passed;public string checkedUtc,scope="Unity Editor: all five original induction challenge types through native Book, formula scroll, proof anchor and check controls. Timeout fixtures age deadlines; physical Android is separate.";public List<Result> checks=new List<Result>();public List<string> errors=new List<string>();}
        static readonly Stack<IEnumerator> stack=new Stack<IEnumerator>();static Report report;static ArchiveTopicSession session;static ArchiveTopicStation station;static ArchiveInductionPresentation art;static ArchiveInductionUI ui;
        static bool active,oldHunting;static double next;static GameObject restriction;
        public static string Status{get;private set;}="Idle";
        static ArchiveStationState State=>session.State.stations[5];
        [MenuItem("Tools/Logic Legends/Open Archive/Topics/Test T6 Induction Court (Play Mode)")]
        public static void Begin(){
            if(!Application.isPlaying||Photon.Pun.PhotonNetwork.InRoom||active)throw new InvalidOperationException("Offline Play Mode required.");session=ArchiveTopicSession.Current;station=session.stations[5];art=station.GetComponent<ArchiveInductionPresentation>();ui=ArchiveTopicUI.Current.GetComponent<ArchiveInductionUI>();
            report=new Report{checkedUtc=DateTime.UtcNow.ToString("o")};stack.Clear();stack.Push(Flow());next=0;oldHunting=session.hunting.enabled;session.hunting.Request(LogicLegends.OpenArchive.Hunting.KhezuCommand.Sleep);session.hunting.enabled=false;active=true;Application.logMessageReceived+=Log;EditorApplication.update+=Tick;
        }
        static void Log(string message,string trace,LogType type){if(type==LogType.Error||type==LogType.Exception||type==LogType.Assert)report.errors.Add(message);}
        static void Tick(){if(!active)return;try{EditorApplication.QueuePlayerLoopUpdate();if(EditorApplication.timeSinceStartup<next)return;if(!Application.isPlaying)throw new InvalidOperationException("Play Mode stopped.");if(stack.Count==0){Finish(true);return;}var flow=stack.Peek();if(!flow.MoveNext()){stack.Pop();return;}if(flow.Current is IEnumerator child)stack.Push(child);else next=EditorApplication.timeSinceStartup+(flow.Current is float delay?delay:0);}catch(Exception e){report.errors.Add(Status+": "+e);Finish(false);}}
        static void Check(bool passed,string name){report.checks.Add(new Result{name=name,passed=passed});if(!passed)throw new InvalidOperationException(name);}
        static void Move(Vector3 p)=>ArchiveTopicPlayChecks.MoveTo(station,p);
        static void Book(){Move(ArchiveTopicStation.BookPosition+Vector3.back*1.7f);station.points.First(p=>p.role==ArchivePointRole.Book).Interact();}
        static IEnumerator Place(int item,int slot){var q=session.Question(5);Move(station.CurrentItemPosition(item,q,State));station.points.First(p=>p.role==ArchivePointRole.Item&&p.index==item).Interact();yield return .055f;Check(State.carries.Any(c=>c.actor==-1&&c.item==item),"Hand takes existing "+q.items[item]);Move(station.SlotPosition(slot,q));station.points.First(p=>p.role==ArchivePointRole.Slot&&p.index==slot).Interact();yield return .055f;Check(State.placements[slot]==item&&State.carries.Count==0,"Hand places "+q.items[item]+" at "+ArchiveInductionPresentation.SlotLabel(slot,q));}
        static IEnumerator Arrange(int[] answer){for(int i=0;i<answer.Length;i++)if(State.placements[i]!=answer[i])yield return Place(answer[i],i);}
        static IEnumerator Submit(){Move(Vector3.zero);ui.CheckButton.onClick.Invoke();yield return .18f;}
        static IEnumerator Preview(string file,bool reading){Move(new Vector3(0,0,6.1f));Player.LocalInstance.transform.rotation=station.transform.rotation*Quaternion.Euler(0,180,0);var look=Player.LocalInstance.GetComponentInChildren<CameraTargetController>();if(look!=null)look.SetViewAngles(27,station.transform.eulerAngles.y+180);if(reading)ArchiveTopicUI.Current.Open(station);else ArchiveTopicUI.Current.Close();yield return .35f;Directory.CreateDirectory("Temp/T6Polish");ScreenCapture.CaptureScreenshot("Temp/T6Polish/"+file+".png");yield return .3f;}
        static IEnumerator Flow(){
            Status="Book and base case";session.Initialize(314159);ArchiveTopicUI.Current.Close();Move(Vector3.zero);yield return .7f;var book=station.GetComponentInChildren<ArchiveAnimatedBook>();Check(book!=null&&book.OpenAmount<.01f,"Existing T6 Book starts closed");Check(!State.timerRunning&&State.timerAttempt==0&&Mathf.Abs(session.TimerRemaining(State)-360)<.01f,"Arrival leaves the six-minute clock unstarted");ArchiveTopicUI.Current.Open(station);yield return .15f;Check(ui.IsOpen&&!State.timerRunning&&!Player.LocalInstance.IsMovementLocked,"Reading the preview neither starts the clock nor locks movement");ArchiveTopicUI.Current.Close();Book();yield return .8f;double deadline=State.timerDeadline;
            Check(State.phase==1&&State.timerRunning&&State.timerAttempt==1&&State.timerActor==-1&&session.TimerRemaining(State)>358,"Native Book starts the shared six-minute induction clock");Check(book.OpenAmount>.98f,"Existing Book opens and floats while induction is active");var q=session.Question(5);Check(q.items.Length==3&&q.slots.SequenceEqual(new[]{"Base:1"})&&art.TokenRoots.Length==3,"First challenge has three original formulas and one Base Case altar");
            for(int i=0;i<q.items.Length;i++){ui.SelectItem(i);Check(ui.ReadingText.text.Contains(q.details[i])&&ui.ReadingText.text.Contains(ArchiveInductionPresentation.FormulaText(q.prompt)),"Reader preserves complete formula and theorem for "+q.items[i]);}Check(string.IsNullOrEmpty(State.reveal)&&!ui.ReadingText.text.Contains("⋯"),"No solved answer is published early and the theorem ellipsis renders safely");ArchiveTopicUI.Current.Close();yield return .1f;var corners=new Vector3[4];ui.Objective.GetWorldCorners(corners);Check(ui.IsObjectiveVisible&&corners.Min(p=>p.x)>Screen.width*.60f&&corners.Max(p=>p.x)<=Screen.width+1,"Compact induction objective stays on the right");Check(!ui.CheckButton.interactable,"Empty anchor cannot be submitted accidentally");
            Move(Vector3.zero);int revision=State.revision;session.Request(5,ArchiveAction.Pick,q.expected[0]);yield return .1f;Check(State.revision==revision&&State.carries.Count==0,"Authority rejects a formula pickup beyond interaction range");yield return Preview("T6_BaseCase",false);yield return Preview("T6_TheoremReader",true);ArchiveTopicUI.Current.Close();yield return Place((q.expected[0]+1)%3,0);
            var particles=art.GetComponentsInChildren<ParticleSystem>().First(p=>p.name=="Induction_Court_Feedback_Sparks");Check(particles.main.maxParticles==24&&!particles.main.loop&&particles.particleCount>0,"Placement emits bounded one-shot feedback particles");yield return .8f;Check(particles.particleCount==0,"Placement particles fade completely instead of accumulating");var ids=art.TokenRoots.Select(t=>t.GetInstanceID()).ToArray();var kept=State.placements.ToArray();yield return Submit();Check(State.round==0&&session.State.mistakes.Count==1&&session.State.mistakes[0].actor==-1&&State.lastAnswerResult==-1,"Wrong base formula records exactly one submitting-player mistake");Check(State.placements.SequenceEqual(kept)&&ids.SequenceEqual(art.TokenRoots.Select(t=>t.GetInstanceID()))&&State.timerDeadline==deadline,"Wrong answer keeps formula objects, arrangement and deadline");
            State.timerDeadline=ArchiveTopicSession.TimerClock-.01;yield return .3f;Check(State.timerExpired&&State.phase==0&&State.round==0&&State.placements.SequenceEqual(kept),"Base timeout retains the unfinished formula choice");Check(session.State.mistakes.Count==2&&session.State.mistakes.Last().reason=="timeout"&&session.State.mistakes.Last().actor==0,"Timeout records one attributed Book-activator mistake");yield return .3f;Check(session.State.mistakes.Count==2,"Expired timer cannot repeatedly charge mistakes");Book();yield return .2f;Check(State.timerAttempt==2&&State.placements.SequenceEqual(kept)&&session.TimerRemaining(State)>359,"Book retry keeps the original formula and starts a new attempt");
            var json=JsonUtility.ToJson(session.State);typeof(ArchiveTopicSession).GetMethod("Receive",BindingFlags.NonPublic|BindingFlags.Instance).Invoke(session,new object[]{json,true});yield return .12f;Check(State.placements.SequenceEqual(kept)&&session.ActiveTopic==5,"Checkpoint restores current formulas and team reservation");yield return Arrange(q.expected);yield return 1.6f;yield return Submit();Check(State.round==1&&State.reveal.Contains(q.details[q.expected[0]])&&State.reveal.Contains("Base case"),"Correct base formula publishes its accepted equality");Check(session.ActiveTopic==5&&Enumerable.Range(0,10).Where(t=>t!=5).All(t=>!session.CanStartTopic(t)),"One unfinished induction topic stays reserved across Book gates");
            Check(State.placements.Length==0,"Solved formula IDs are cleared at the next Book gate");State.timerDeadline=ArchiveTopicSession.TimerClock-.01;yield return .3f;Check(State.timerExpired&&State.round==1&&State.placements.Length==0,"Gate timeout keeps solved progress without pre-answering the next single-slot challenge");Book();yield return .2f;q=session.Question(5);deadline=State.timerDeadline;Check(State.timerAttempt==3&&State.placements.SequenceEqual(new[]{-1})&&q.slots.SequenceEqual(new[]{"Hypothesis:1"}),"Hypothesis starts with its own empty anchor after a gate timeout");
            Status="Hypothesis and goal";yield return Place((q.expected[0]+1)%3,0);int before=session.State.mistakes.Count;yield return Submit();Check(State.round==1&&session.State.mistakes.Count==before+1&&State.timerDeadline==deadline,"Base/goal distractor cannot replace the inductive hypothesis");yield return Arrange(q.expected);yield return 1.6f;yield return Submit();Check(State.round==2&&State.reveal.Contains("Inductive hypothesis"),"Correct arbitrary-k assumption completes the hypothesis challenge");Book();yield return .2f;q=session.Question(5);Check(q.slots.SequenceEqual(new[]{"Step:1"})&&station.workRoot.GetComponentsInChildren<TMP_Text>().Any(t=>t.text=="GOAL · P(k + 1)"),"Goal challenge has a clearly named P(k + 1) anchor");yield return Arrange(q.expected);yield return Submit();Check(State.round==3&&State.reveal.Contains(q.details[q.expected[0]])&&State.timerDeadline==deadline,"Correct next-step statement retains the running team deadline");
            Status="Four-line inductive step";Book();yield return .2f;q=session.Question(5);Check(q.items.Length==4&&q.slots.Length==4&&station.workRoot.Cast<Transform>().Count(t=>t.name.StartsWith("Inductive_Chain_Link_"))==3,"Inductive step has four formula sockets joined in proof order");yield return Arrange(q.expected.Reverse().ToArray());kept=State.placements.ToArray();ids=art.TokenRoots.Select(t=>t.GetInstanceID()).ToArray();before=session.State.mistakes.Count;yield return Submit();Check(State.round==3&&session.State.mistakes.Count==before+1&&State.placements.SequenceEqual(kept)&&ids.SequenceEqual(art.TokenRoots.Select(t=>t.GetInstanceID())),"Incorrect inductive order keeps all four physical formulas and records one mistake");State.timerDeadline=ArchiveTopicSession.TimerClock-.01;yield return .3f;Check(State.timerExpired&&State.round==3&&State.placements.SequenceEqual(kept),"Step timeout retains all four current lines");Book();yield return .2f;Check(State.timerAttempt==4&&State.placements.SequenceEqual(kept),"Step retry retains the existing proof chain");yield return Arrange(q.expected);yield return 1.6f;yield return Submit();Check(State.round==4&&State.reveal.Contains(q.details[q.expected.Last()]),"Ordered append/substitute/combine/factor chain completes the inductive step");
            Status="Full induction proof";Book();yield return .2f;q=session.Question(5);Check(q.items.Length==6&&q.slots.SequenceEqual(new[]{"Base:1","Hypothesis:1","Step:1","Step:2","Step:3","Step:4"}),"Final challenge uses all three regions and all six original formulas");yield return Preview("T6_FullCourt",false);yield return Preview("T6_FullProofReader",true);ui.SelectItem(q.itemOrder.Last());yield return .25f;ScreenCapture.CaptureScreenshot("Temp/T6Polish/T6_FormulaReader.png");yield return .3f;ArchiveTopicUI.Current.Close();
            Move(station.CurrentItemPosition(q.expected[0],q,State));restriction=new GameObject("T6 movement restriction fixture");Player.LocalInstance.AcquireMovementLock(restriction,"T6 capture validation",Player.LocalInstance.transform.position,100);revision=State.revision;session.Request(5,ArchiveAction.Pick,q.expected[0]);yield return .12f;Check(!session.CanAct(-1)&&State.revision==revision&&!ui.IsObjectiveVisible,"Existing capture/stun lock rejects a nearby formula pickup and hides the objective");Player.LocalInstance.ReleaseMovementLock(restriction);UnityEngine.Object.Destroy(restriction);restriction=null;
            yield return Place(q.expected[0],0);yield return Place(q.expected[1],1);kept=State.placements.ToArray();State.timerDeadline=ArchiveTopicSession.TimerClock-.01;yield return .3f;Check(State.timerExpired&&State.round==4&&State.placements.SequenceEqual(kept),"Final timeout retains the team's Base and Hypothesis work");Book();yield return .2f;Check(State.timerAttempt==5&&State.placements.SequenceEqual(kept),"Final Book retry keeps all existing proof regions");yield return Arrange(q.expected);foreach(var text in station.workRoot.GetComponentsInChildren<TMP_Text>()){text.ForceMeshUpdate();Check(!text.isTextOverflowing,"World proof label fits: "+text.text);}yield return Submit();
            Check(State.phase==2&&State.round==5&&!State.timerRunning&&session.ActiveTopic==-1,"Five induction challenges freeze the clock and release the next topic");Check(State.reveal.Contains("for every integer n ≥ 1")&&q.details.All(d=>State.reveal.Contains(d)),"Accepted full proof publishes every formula and its induction conclusion");float remaining=session.TimerRemaining(State);yield return .2f;Check(session.TimerRemaining(State)==remaining,"Completed induction clock remains frozen");Check(session.State.stations.Where(s=>s.topic!=5).All(s=>s.round==0&&s.timerAttempt==0),"T6 preserves every other topic's progress and timer");Check(!Player.LocalInstance.IsMovementLocked&&Time.timeScale==1&&report.errors.Count==0,"Reader never pauses the world or locks movement; no runtime errors");Status="Passed";
        }
        [MenuItem("Tools/Logic Legends/Open Archive/Topics/Validate T6 Induction Variants")]
        public static string ValidateVariants(){
            var catalog=AssetDatabase.LoadAssetAtPath<ArchiveTopicCatalog>(ArchiveTopicSetup.Folder+"/Archive_Topic_Catalog.asset");var checks=new List<Result>();var failures=new List<string>();int variants=0,numericCases=0;
            Action<bool,string> test=(passed,name)=>{checks.Add(new Result{name=name,passed=passed});if(!passed)failures.Add(name);};
            try{for(int r=0;r<5;r++)for(int v=0;v<InductionChallenges.VariantsPerChallenge;v++){
                var source=InductionChallenges.VariantSets[r][v];int seed=Enumerable.Range(1,4096).First(s=>ArchiveTopicQuestions.Build(catalog,5,r,s).prompt==source.theorem);var q=ArchiveTopicQuestions.Build(catalog,5,r,seed);var good=ArchiveTopicChecks.Solution(q);string message;variants++;string id="Challenge "+(r+1)+" / variant "+(v+1);
                test(ArchiveTopicQuestions.Validate(q,good,out message),id+" accepts authored mathematical IDs");test(q.details.SequenceEqual(source.choices.Select(c=>c.expression))&&q.prompt==source.theorem,id+" preserves the complete original theorem and formulas");test(q.slots.All(key=>source.answers.ContainsKey(key))&&q.slots.Select((key,i)=>source.choices[q.expected[i]].id==source.answers[key]).All(x=>x),id+" keeps the original anchor-to-formula mapping");
                var bad=ArchiveTopicChecks.Solution(q);bad.placements[0]=(bad.placements[0]+1)%q.items.Length;test(!ArchiveTopicQuestions.Validate(q,bad,out message),id+" rejects a distractor or misplaced line");bad.placements[0]=-1;test(!ArchiveTopicQuestions.Validate(q,bad,out message),id+" rejects an empty required anchor");
                if(q.slots.Length>1){bad=ArchiveTopicChecks.Solution(q);Array.Reverse(bad.placements);test(!ArchiveTopicQuestions.Validate(q,bad,out message),id+" rejects reversed proof order");bad=ArchiveTopicChecks.Solution(q);bad.placements[0]=bad.placements[1];test(!ArchiveTopicQuestions.Validate(q,bad,out message),id+" rejects a repeated physical scroll");}
                var points=Enumerable.Range(0,q.items.Length).Select(i=>ArchiveInductionPresentation.TokenPosition(i,q)).ToArray();var sockets=Enumerable.Range(0,q.slots.Length).Select(i=>ArchiveInductionPresentation.SocketPosition(i,q)).ToArray();test(points.Distinct().Count()==points.Length&&sockets.Distinct().Count()==sockets.Length&&points.Concat(sockets).All(p=>new Vector2(p.x,p.z).magnitude<8),id+" fits distinct formulas and anchors inside the court");
                string reveal=ArchiveTopicQuestions.InductionReveal(q,good);test(q.expected.All(i=>reveal.Contains(q.details[i])),id+" publishes the accepted formula choices");bool math=true;for(int k=1;k<=8;k++){math&=NumericProof(source,k);numericCases++;}test(math,id+" agrees numerically with the original arithmetic sequence for k = 1 through 8");
            }
            var font=AssetDatabase.LoadAssetAtPath<TMP_FontAsset>("Assets/RulesOfInferenceUI/InferenceBody.asset");var text=string.Join("",InductionChallenges.VariantSets.SelectMany(s=>s).Select(q=>q.theorem+q.instructions+string.Join("",q.choices.Select(c=>c.expression))))+"P(k) → P(k + 1)";
            test(ArchiveInductionPresentation.FormulaText(text).Where(c=>!char.IsWhiteSpace(c)).Distinct().All(c=>font.HasCharacter(c,true,false)),"Existing reading font renders every displayed induction character with the scoped ellipsis substitution");
            }catch(Exception e){failures.Add(e.ToString());}
            var data=new{passed=failures.Count==0,variants=variants,numericCases=numericCases,checks=checks,failures=failures};Directory.CreateDirectory(ArchiveTopicSetup.Folder+"/Testing/Reports");File.WriteAllText(ArchiveTopicSetup.Folder+"/Testing/Reports/T6InductionVariants.json",Newtonsoft.Json.JsonConvert.SerializeObject(data,Newtonsoft.Json.Formatting.Indented));return(data.passed?"Passed":"Failed")+": "+variants+" variants, "+checks.Count+" checks, "+numericCases+" numeric cases";
        }
        // QA only: independently evaluate the authored identities against sums of the given arithmetic terms.
        static bool NumericProof(InductionChallenge q,int k){
            var match=Regex.Match(q.theorem,@"^S\(n\) = \((\d+)\) \+ \((\d+)\)");int first=int.Parse(match.Groups[1].Value),a=int.Parse(match.Groups[2].Value)-first,b=first-a;
            Func<int,double> sum=n=>Enumerable.Range(1,n).Sum(i=>(double)(a*i+b));
            Func<string,double> calc=value=>{string expanded=Regex.Replace(value,@"S\(([^)]+)\)",m=>sum((int)Math.Round(new Arithmetic(m.Groups[1].Value,k).Value())).ToString(CultureInfo.InvariantCulture));return new Arithmetic(expanded,k).Value();};
            if(Math.Abs(calc(q.theorem.Split('=')[2].Split(',')[0])-sum(k))>.00001)return false;
            foreach(var answer in q.answers){var formula=q.choices.First(c=>c.id==answer.Value).expression.Replace("Assume ","");double target=answer.Key.StartsWith("Base:")?sum(1):answer.Key.StartsWith("Hypothesis:")?sum(k):sum(k+1);foreach(var side in formula.Split('=').Where(s=>!string.IsNullOrWhiteSpace(s)))if(Math.Abs(calc(side)-target)>.00001)return false;}
            return true;
        }
        sealed class Arithmetic{
            readonly string text;readonly int k;int at;public Arithmetic(string source,int variable){text=Regex.Replace(source,"\\s+","").Replace('−','-').Replace('[','(').Replace(']',')');k=variable;}
            public double Value(){double n=Sum();if(at!=text.Length)throw new FormatException("Unexpected arithmetic token: "+text.Substring(at));return n;}
            double Sum(){double n=Product();while(at<text.Length&&(text[at]=='+'||text[at]=='-')){char op=text[at++];double value=Product();n=op=='+'?n+value:n-value;}return n;}
            double Product(){double n=Atom();while(at<text.Length){char op=text[at];if(op=='*'||op=='/'){at++;double value=Atom();n=op=='*'?n*value:n/value;}else if(op=='('||op=='k'||op=='n'||char.IsDigit(op))n*=Atom();else break;}return n;}
            double Atom(){if(at>=text.Length)throw new FormatException("Missing arithmetic term.");char c=text[at++];if(c=='+')return Atom();if(c=='-')return -Atom();if(c=='k'||c=='n')return k;if(c=='('){double n=Sum();if(at>=text.Length||text[at++]!=')')throw new FormatException("Missing parenthesis.");return n;}if(char.IsDigit(c)){int start=at-1;while(at<text.Length&&(char.IsDigit(text[at])||text[at]=='.'))at++;return double.Parse(text.Substring(start,at-start),CultureInfo.InvariantCulture);}throw new FormatException("Unexpected arithmetic atom: "+c);}
        }
        static void Finish(bool success){active=false;EditorApplication.update-=Tick;Application.logMessageReceived-=Log;stack.Clear();if(restriction!=null){Player.LocalInstance.ReleaseMovementLock(restriction);UnityEngine.Object.Destroy(restriction);}if(session!=null&&Application.isPlaying){session.hunting.enabled=oldHunting;session.hunting.Request(LogicLegends.OpenArchive.Hunting.KhezuCommand.Sleep);ArchiveTopicUI.Current.Close();}report.passed=success&&report.errors.Count==0&&report.checks.All(c=>c.passed);Status=report.passed?"Passed":"Failed";Directory.CreateDirectory(ArchiveTopicSetup.Folder+"/Testing/Reports");File.WriteAllText(ArchiveTopicSetup.Folder+"/Testing/Reports/T6PolishPlayMode.json",JsonUtility.ToJson(report,true));Debug.Log("T6 Induction Court: "+Status+", "+report.checks.Count+" checks");}
    }
